          "value" : "catalog[1].group[23].group[4]"
        } ],
        "parts" : [ {
          "name" : "overview",
          "prose" : "# Context\n\nWhen using IT equipment or applications that implement IPsec, security controls for using AACAs and AACPs in the ‘Cryptographic algorithms’ and ‘Cryptographic protocols’ sections of these guidelines will also need to be consulted."
        } ],
        "groups" : [ {
          "title" : "Mode of operation",
